<script setup lang="ts">
import { computed, reactive, ref, watch } from 'vue'
import { useQuery } from '@tanstack/vue-query'
import { ElMessage } from '@/app/messages'
import { getAiEntitlements, listStudyPlans, createStudyPlan, adjustStudyPlan, archiveStudyPlan, createPrivateProblem, listPrivateProblems, getAiTask } from '@/api/ai'
import type { AiTask } from '@/api/ai'
import { readableError } from '@/api/errors'
import { useSession } from '@/composables/useSession'
import { readPlanTask, writePlanTask } from '@/features/plans/taskStorage'

const session=useSession(), goal=ref(''), changeRequest=ref(''), taskId=ref(''), busy=ref(false)
watch(()=>session.user.value?.id, id=>{taskId.value=readPlanTask(id);goal.value='';changeRequest.value=''}, {immediate:true})
const form=reactive({level:'基础',tags:'数组,哈希表',days:14,minutesPerDay:45,sourceMode:'CATALOG' as 'CATALOG'|'MIXED'})
const loggedIn=computed(()=>Boolean(session.user.value?.id))
const entitlements=useQuery({queryKey:computed(()=>['ai-entitlements',session.user.value?.id]),enabled:loggedIn,queryFn:({signal})=>getAiEntitlements(signal),retry:false})
const plans=useQuery({queryKey:computed(()=>['ai-plans',session.user.value?.id]),enabled:loggedIn,queryFn:({signal})=>listStudyPlans(signal),retry:false,refetchInterval:q=>q.state.error?false:q.state.data?.some(v=>v.status==='GENERATING'||v.status==='ADJUSTING'||v.items.some(i=>i.source==='PRIVATE'&&i.title==='AI 题目生成中'))?2500:false})
const privateProblems=useQuery({queryKey:computed(()=>['private-problems',session.user.value?.id]),enabled:loggedIn,queryFn:({signal})=>listPrivateProblems(signal),retry:false,refetchInterval:q=>q.state.error?false:q.state.data?.some(v=>v.status==='GENERATING')?2500:false})
const task=useQuery({queryKey:computed(()=>['ai-task',session.user.value?.id,taskId.value]),queryFn:({signal})=>getAiTask(taskId.value,signal),enabled:computed(()=>Boolean(session.user.value?.id&&taskId.value)),retry:false,refetchInterval:q=>q.state.error||['SUCCEEDED','FAILED','CANCELLED'].includes((q.state.data as AiTask|undefined)?.status??'')?false:2000})
const activePlan=computed(()=>plans.data.value?.find(v=>v.status==='ACTIVE'||v.status==='GENERATING'||v.status==='ADJUSTING'||v.status==='NEEDS_REVIEW'))
const isVip=computed(()=>Boolean(entitlements.data.value?.vipActive))
async function create(){if(!goal.value.trim()){ElMessage.warning({ message: '请填写学习目标' });return}const ownerId=session.user.value?.id;busy.value=true;try{const result=await createStudyPlan({goal:goal.value.trim(),level:form.level,tags:form.tags.split(',').map(x=>x.trim()).filter(Boolean),days:form.days,minutesPerDay:form.minutesPerDay,sourceMode:form.sourceMode,idempotencyKey:crypto.randomUUID()});setTask(result.taskId,ownerId);ElMessage.success({ message: '学习计划已加入队列' });await plans.refetch()}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
async function adjust(){if(!activePlan.value||!changeRequest.value.trim())return;const ownerId=session.user.value?.id;busy.value=true;try{const result=await adjustStudyPlan(activePlan.value.id,{changeRequest:changeRequest.value.trim(),expectedVersion:activePlan.value.planVersion,idempotencyKey:crypto.randomUUID()});setTask(result.taskId,ownerId);changeRequest.value='';await plans.refetch()}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
async function archive(){if(!activePlan.value)return;busy.value=true;try{await archiveStudyPlan(activePlan.value.id,activePlan.value.planVersion);ElMessage.success({ message: '计划已归档' });await plans.refetch()}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
async function generatePrivate(){if(!goal.value.trim()){ElMessage.warning({ message: '请在学习目标中描述私人题方向' });return}const ownerId=session.user.value?.id;busy.value=true;try{const result=await createPrivateProblem({goal:goal.value.trim(),difficulty:'MEDIUM',tags:form.tags.split(',').map(x=>x.trim()).filter(Boolean),idempotencyKey:crypto.randomUUID()});setTask(result.taskId,ownerId);ElMessage.success({ message: '私人题已加入生成队列' })}catch(e){ElMessage.error({ message: readableError(e) })}finally{busy.value=false}}
function setTask(id:string,ownerId:string|undefined){if(!ownerId||session.user.value?.id!==ownerId)return;taskId.value=id;writePlanTask(ownerId,id)}
</script>
<template><div class="page plans-page">
  <div class="page-head"><div><h1 class="page-title">AI 学习计划</h1><p class="page-lead">根据你的目标安排题库练习；VIP 可生成混合题单和仅自己可见的练习题。</p></div><el-button @click="plans.refetch();privateProblems.refetch()">刷新</el-button></div>
  <el-alert v-if="task.data.value" :type="task.data.value.status==='FAILED'?'error':task.data.value.status==='SUCCEEDED'?'success':'info'" :closable="false" class="task-alert" :title="`最近任务：${task.data.value.status==='QUEUED'?'排队中':task.data.value.status==='RUNNING'?'处理中':task.data.value.status==='SUCCEEDED'?'已完成':'失败'}`"><template v-if="task.data.value.message">{{task.data.value.message}}</template></el-alert>
  <section class="surface create-card"><div class="section-title"><div><h2>生成计划</h2><p>支持 7–30 天，可选择仅题库或混合题单。</p></div><el-tag :type="isVip?'warning':'info'">{{isVip?'VIP':'普通用户'}}</el-tag></div>
    <el-form label-position="top" class="plan-form"><el-form-item label="学习目标"><el-input v-model="goal" maxlength="1000" type="textarea" :rows="3" placeholder="例如：用两周巩固链表、二叉树和动态规划基础"/></el-form-item>
      <div class="form-grid"><el-form-item label="当前水平"><el-input v-model="form.level" maxlength="32"/></el-form-item><el-form-item label="关注标签（逗号分隔）"><el-input v-model="form.tags"/></el-form-item><el-form-item label="天数"><el-input-number v-model="form.days" :min="7" :max="30"/></el-form-item><el-form-item label="每天分钟数"><el-input-number v-model="form.minutesPerDay" :min="10" :max="240"/></el-form-item><el-form-item label="题目来源"><el-select v-model="form.sourceMode"><el-option label="题库题目" value="CATALOG"/><el-option label="混合题单（最多 5 道私人题）" value="MIXED" :disabled="!isVip"/></el-select></el-form-item></div>
      <div class="actions"><el-button type="primary" :loading="busy" :disabled="!entitlements.data.value?.planEnabled||Boolean(activePlan&&activePlan.status!=='NEEDS_REVIEW')" @click="create">创建学习计划</el-button><el-button :loading="busy" :disabled="!entitlements.data.value?.privateProblemsEnabled" @click="generatePrivate">单独生成私人题</el-button><span v-if="!entitlements.data.value?.planEnabled" class="muted">AI 服务尚未配置或当前账号不具备 VIP 权益。</span></div>
    </el-form>
  </section>
  <section v-if="activePlan" class="surface plan-card"><div class="section-title"><div><h2>{{activePlan.title}}</h2><p>{{activePlan.goal}} · {{activePlan.days}} 天 · 每日 {{activePlan.minutesPerDay}} 分钟 · 版本 {{activePlan.planVersion}}</p></div><div class="actions"><el-tag>{{activePlan.status}}</el-tag><el-button size="small" @click="plans.refetch()">刷新计划</el-button><el-button size="small" type="danger" plain :disabled="activePlan.status==='GENERATING'||activePlan.status==='ADJUSTING'" @click="archive">归档</el-button></div></div>
    <el-progress :percentage="activePlan.items.length?Math.round(activePlan.completedCount/activePlan.items.length*100):0" :format="()=>`${activePlan?.completedCount ?? 0}/${activePlan?.items.length ?? 0} 已完成`"/>
    <div class="items"><article v-for="item in activePlan.items" :key="item.id" class="plan-item"><div class="day">第 {{item.dayNumber}} 天<small>第 {{item.orderNumber}} 题</small></div><div class="item-main"><strong>{{item.title}}</strong><p>{{item.reason}}</p></div><el-tag :type="item.status==='DONE'?'success':item.status==='UNAVAILABLE'?'danger':'info'">{{item.status==='DONE'?'已打卡':item.status==='UNAVAILABLE'?'不可用':'待完成'}}</el-tag><RouterLink v-if="item.source==='PUBLIC'&&item.problemNo" :to="`/problems/${item.problemNo}`">去练习</RouterLink><RouterLink v-else-if="item.privateProblemId" :to="`/private-problems/${item.privateProblemId}`">{{item.title==='AI 题目生成中'?'生成中…':'去练习'}}</RouterLink></article></div>
    <div class="adjust"><el-input v-model="changeRequest" placeholder="告诉 Agent 如何调整未完成任务" maxlength="1000"/><el-button :disabled="!entitlements.data.value?.planEnabled||!activePlan.items.length" :loading="busy" @click="adjust">调整计划</el-button></div>
  </section>
  <section class="surface plan-card"><div class="section-title"><div><h2>我的私人题</h2><p>仅你可以查看和提交，生成失败时不会进入题库。</p></div><el-button link @click="privateProblems.refetch()">刷新</el-button></div><div v-if="!privateProblems.data.value?.length" class="empty">尚无私人题。</div><article v-for="problem in privateProblems.data.value" :key="problem.id" class="private-row"><div><strong>{{problem.title}}</strong><p>{{problem.tags.join(' · ')}} · {{problem.difficulty}}</p><small v-if="problem.rejectReason">{{problem.rejectReason}}</small></div><el-tag :type="problem.status==='READY'?'success':problem.status==='REJECTED'?'danger':'info'">{{problem.status==='READY'?'可练习':problem.status==='REJECTED'?'未通过验证':'生成中'}}</el-tag><RouterLink v-if="problem.status==='READY'" :to="`/private-problems/${problem.id}`">打开</RouterLink></article></section>
</div></template>
<style scoped>.plans-page{max-width:1280px}.task-alert{margin-bottom:16px}.create-card,.plan-card{padding:22px;margin-bottom:18px}.section-title{display:flex;justify-content:space-between;align-items:flex-start;gap:16px;margin-bottom:18px}.section-title h2{margin:0;font-size:18px}.section-title p,.plan-item p,.private-row p{margin:6px 0 0;color:var(--oj-text-muted);font-size:13px}.plan-form :deep(.el-form-item){margin-bottom:14px}.form-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px 16px}.form-grid :deep(.el-input-number),.form-grid :deep(.el-select){width:100%}.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.muted,.empty{font-size:13px;color:var(--oj-text-muted)}.items{margin-top:18px}.plan-item,.private-row{display:flex;align-items:center;gap:18px;padding:14px 4px;border-bottom:1px solid var(--oj-border)}.day{width:90px;flex:none;font-size:13px}.day small{display:block;color:var(--oj-text-muted);margin-top:4px}.item-main{min-width:0;flex:1}.item-main p{font-size:12px}.plan-item a,.private-row a{color:var(--oj-accent)}.private-row>div{flex:1}.private-row small{color:var(--oj-danger)}.adjust{display:flex;gap:10px;margin-top:16px}.adjust .el-input{flex:1}@media(max-width:800px){.form-grid{grid-template-columns:1fr 1fr}.plan-item{gap:10px;flex-wrap:wrap}.day{width:70px}.adjust{flex-direction:column}}@media(max-width:520px){.form-grid{grid-template-columns:1fr}}</style>
